            shape: 'a short clause: the heavier side', expect: 'the gains far outweigh the losses (also accepted: the benefits clearly prevail; the advantages are the weightier)',
            accept: [['gains|benefits|advantages|openness'], ['outweigh|prevail|weightier|heavier|greater']],
            reject: [{ re: 'evenly|equal|matched|balanced', hint: 'A fence-sit contradicts your thesis.' },
              { re: '(losses|costs|drawbacks|disadvantages) (far |clearly )?outweigh', hint: 'That switches sides.' },
              { re: 'gains (far |clearly )?outweighs', hint: 'Check agreement.' }],
